// ─────────────────────────────────────────────────────────────────────────
// LE ZONE DEL GUSTO DEL MONDO — costruite sui NOSTRI dati, non a intuito
//
// Solo DATI: nessuna logica, nessun import (come libraryZonesWorld.ts).
//
// Da dove vengono. L'import enogastronomico da OpenStreetMap ha portato in
// shared_pois circa 199.000 luoghi del gusto in 215 paesi — cantine,
// caseifici, frantoi, birrifici, torrefazioni, pasticcerie. Questo catalogo
// e' il risultato di averli CONTATI: griglia da 25 km, celle adiacenti
// accorpate, centro pesato sui POI, e tenute solo le zone con almeno 25
// produttori veri nel raggio (scratch/zone-gusto-20260820.mjs e
// scratch/genera-tastezones-20260820.mjs).
//
// Perche' contarli invece di sceglierli. Il catalogo scritto a mano
// (wineRoutesCatalog.ts) e' curato ma sbilanciato per forza di cose: 98
// percorsi su 130 sono di vino e 87 su 130 stanno in Europa, perche' quelle
// sono le strade del gusto di cui si scrive. Contare i produttori fa
// emergere invece Taipei, Buenos Aires, Katmandu, Bangalore, Oakland: zone
// dove il gusto c'e' davvero e nessuna guida italiana lo racconta.
//
// I nomi. Il geocoder, al centro di una zona agricola, risponde col nome
// della frazione piu' vicina: nessuno cerca "due giorni del gusto a
// Bannewitz". Quindi le zone entro 45 km da una citta' gia' a catalogo
// prendono il nome di quella citta', le altre prendono il nome della
// REGIONE — che e' la scala con cui una zona del gusto e' conosciuta.
//
// NON si scrivono qui i nomi dei produttori: cambiano, chiudono, e un nome
// inventato e' il difetto peggiore che possiamo avere. Li mette il
// generatore pescandoli dal database (server.ts::libFetchGusto).
// ─────────────────────────────────────────────────────────────────────────

export interface TasteZone {
  /** Nome della zona: citta' se urbana, regione se agricola. */
  c: string;
  /** Paese, in italiano. */
  k: string;
  lat: number;
  lon: number;
  /** Quanti POI del gusto abbiamo contato nella zona. */
  n: number;
  /** Priorita' di semina: 1 = densita' altissima, 2 = alta, 3 = media. */
  t: 1 | 2 | 3;
  /** Zona urbana (true) o campagna di produzione (false). */
  u: boolean;
  /** La zona vive di produzione agricola: si guida tra i poderi. */
  a: boolean;
  /** I tre prodotti dominanti, come li chiamerebbe una guida. */
  p: string;
}

